package dev.workshopvideo;
import android.app.Activity;import android.content.res.ColorStateList;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.function.Consumer;
/** Live controls, shared by every locally supported wallpaper type. */
final class EffectPanel extends LinearLayout {
 private final Activity activity;private final Consumer<JSONObject> changed;private JSONObject value;private final boolean hasSensor;private final String kind;private int layerCount;private float[] layerDepths;private String[] layerNames;private boolean xray;private LinearLayout palette;private TextView paletteHint;private LinearLayout videoCard;private View colorChip;private TextView colorName;
 EffectPanel(Activity activity,JSONObject initial,boolean sensor,String kind,Consumer<JSONObject> changed){super(activity);this.activity=activity;this.changed=changed;this.hasSensor=sensor;this.kind=kind;value=kind.equals("video")?EffectOptions.video(initial):EffectOptions.normalize(initial);setOrientation(VERTICAL);build();}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String s,int size,int color){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(10),0,dp(7));return t;}
 private void control(View view,LayoutParams p){if(videoCard!=null)videoCard.addView(view,p);else addView(view,p);}
 private void control(View view){control(view,new LayoutParams(-1,-2));}
 private void heading(String s){if(kind.equals("video")){videoCard=new LinearLayout(activity);videoCard.setOrientation(VERTICAL);videoCard.setPadding(dp(14),dp(4),dp(14),dp(12));videoCard.setBackground(AppSheet.background(Ui.PANEL,dp(18)));LayoutParams p=new LayoutParams(-1,-2);p.topMargin=dp(12);addView(videoCard,p);videoCard.addView(label(s,14,Ui.ACCENT));}else addView(label(s,15,Ui.ACCENT));}
 private void changed(){changed.accept(kind.equals("video")?EffectOptions.video(value):EffectOptions.normalize(value));}
 private void toggle(String key,String title,boolean enabled){Switch s=new Switch(activity);s.setText(title);s.setTextSize(13);s.setTextColor(Ui.TEXT);s.setMinHeight(dp(46));s.setPadding(0,dp(6),0,dp(6));s.setChecked(enabled&&value.optBoolean(key,key.equals("xray")));s.setEnabled(enabled);s.setAlpha(enabled?1:.45f);s.setThumbTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Ui.ACCENT,0xff81909f}));s.setTrackTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xff355c51,0xff303d4b}));s.setOnCheckedChangeListener((b,on)->{VideoApp.put(value,key,on);updatePalette();changed();});control(s);}
 private void slider(String key,String title,float min,float max,String suffix){
  float initial=(float)value.optDouble(key,key.equals("xraySize")?.3:min);LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView name=label(title,12,Ui.TEXT);header.addView(name,new LayoutParams(0,-2,1));TextView number=label(number(key,initial)+suffix,12,Ui.ACCENT);number.setPadding(dp(8),dp(3),dp(8),dp(3));number.setBackground(AppSheet.background(0xff213731,dp(8)));header.addView(number);control(header);
  SeekBar bar=new SeekBar(activity);bar.setMax(key.equals("fallbackPages")?11:1000);bar.setProgress(Math.round((initial-min)/(max-min)*bar.getMax()));bar.setProgressTintList(ColorStateList.valueOf(Ui.ACCENT));bar.setProgressBackgroundTintList(ColorStateList.valueOf(0xff344454));bar.setThumbTintList(ColorStateList.valueOf(Ui.ACCENT));bar.setContentDescription(title);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(!user)return;float next=min+(max-min)*p/s.getMax();if(key.equals("fallbackPages"))next=Math.round(next);VideoApp.put(value,key,next);number.setText(number(key,next)+suffix);changed();}});control(bar,new LayoutParams(-1,dp(34)));
 }
 private String number(String key,float value){return key.equals("fallbackPages")||key.equals("fps")||key.equals("hue")?String.valueOf(Math.round(value)):format(value);}
 private String format(float f){return String.format(Locale.CHINA,"%.2f",f);}
 void sceneLayers(float[] depths,String[] names,boolean xray){layerDepths=depths;layerNames=names;this.xray=xray;if(xray){heading("触摸透视");toggle("xray","按住并拖动查看另一层图片",true);slider("xraySize","揭示范围",.01f,1,"");}int count=depths.length;layerCount=count;heading("分层参数");for(int i=0;i<Math.min(32,count);i++){heading(names!=null&&i<names.length?names[i]:"图层 "+(i+1));if(!value.has("depth"+i))VideoApp.put(value,"depth"+i,depths[i]);if(!value.has("opacity"+i))VideoApp.put(value,"opacity"+i,1);slider("depth"+i,"视差深度",-2,2,"");slider("opacity"+i,"不透明度",0,1,"");slider("layerX"+i,"水平移动",-1,1,"");slider("layerY"+i,"垂直移动",-1,1,"");}}
 private void updatePalette(){if(palette==null)return;boolean active=value.optBoolean("ripple")||value.optBoolean("particles");palette.setVisibility(active?VISIBLE:GONE);String selected=value.optString("color","#a9efd5");LinearLayout colors=(LinearLayout)palette.getChildAt(2);String[] names={"薄荷绿","天空蓝","樱花粉","暖金色","白色"};String chosen="";for(int i=0;i<colors.getChildCount();i++){TextView view=(TextView)colors.getChildAt(i);boolean on=selected.equalsIgnoreCase(String.valueOf(view.getTag()));view.setSelected(on);view.setText(on?"✓":"●");android.graphics.drawable.GradientDrawable bg=AppSheet.background(on?0xff243e40:Ui.PANEL,dp(14));bg.setStroke(dp(on?2:1),on?Color.parseColor(selected):0xff263343);android.widget.LinearLayout.LayoutParams lp=(LayoutParams)view.getLayoutParams();lp.setMargins(dp(3),0,dp(3),0);view.setBackground(bg);view.setContentDescription(names[i]+(on?"，已选择":""));if(on)chosen=names[i];}paletteHint.setText("已选："+chosen+" · 仅改变波纹与粒子颜色");}
 private void choice(String key,String title,String[] keys,String[] labels){
  control(label(title,13,Ui.TEXT));LinearLayout strip=new LinearLayout(activity);strip.setPadding(dp(4),dp(4),dp(4),dp(4));strip.setBackground(AppSheet.background(0xff0d1520,dp(14)));
  for(int i=0;i<keys.length;i++){String item=keys[i];boolean selected=item.equals(value.optString(key,keys[0]));boolean available=!key.equals("motionMode")||!item.equals("device")||hasSensor;TextView option=label(labels[i],13,selected?0xff15372d:Ui.MUTED);option.setGravity(Gravity.CENTER);option.setMinHeight(dp(42));option.setPadding(dp(4),dp(8),dp(4),dp(8));option.setMaxLines(2);option.setSelected(selected);option.setEnabled(available);option.setAlpha(available?1:.35f);option.setTag("choice-"+key+"-"+item);option.setContentDescription(title+"，"+labels[i]+(selected?"，已选择":""));option.setBackground(new android.graphics.drawable.RippleDrawable(ColorStateList.valueOf(0x22ffffff),AppSheet.background(selected?Ui.ACCENT:0x00000000,dp(10)),null));option.setOnClickListener(v->{VideoApp.put(value,key,item);if(key.equals("motionMode")){VideoApp.put(value,"pan",item.equals("scroll"));VideoApp.put(value,"gyro",item.equals("device"));VideoApp.put(value,"touch",false);VideoApp.put(value,"ripple",false);VideoApp.put(value,"particles",false);}build();changed();});LayoutParams p=new LayoutParams(0,-2,1);if(i>0)p.leftMargin=dp(3);strip.addView(option,p);}
  control(strip);
  String hint="";if(key.equals("alignment"))hint=switch(value.optString(key)){case "fill"->"拉伸画面，填满整个屏幕";case "free"->"保持完整画面，可自由调整缩放与位置";default->"按原比例铺满屏幕，裁切超出部分";};
  if(key.equals("motionMode"))hint=switch(value.optString(key)){case "device"->"倾斜手机时，画面跟随产生视差";case "scroll"->"左右翻动桌面时，背景跟随移动";default->"保持画面位置";};
  if(!hint.isEmpty()){TextView detail=label(hint,11,Ui.MUTED);detail.setPadding(0,dp(7),0,dp(3));control(detail);}
 }
 private void updateColorRow(){if(colorChip==null)return;int selected=Color.parseColor(value.optString("backgroundColor","#000000"));android.graphics.drawable.GradientDrawable chip=AppSheet.background(selected,dp(12));chip.setStroke(dp(1),0xff4a596b);colorChip.setBackground(chip);colorName.setText(WallpaperColorPicker.name(selected)+" · 点击选择");}
 private void backgroundColor(){
  LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),dp(10),dp(12),dp(10));row.setBackground(AppSheet.background(0xff101925,dp(14)));row.setTag("background-color");colorChip=new View(activity);row.addView(colorChip,new LayoutParams(dp(42),dp(42)));LinearLayout words=new LinearLayout(activity);words.setOrientation(VERTICAL);words.setPadding(dp(12),0,0,0);TextView title=label("背景颜色",13,Ui.TEXT);title.setPadding(0,0,0,dp(4));words.addView(title);colorName=label("",11,Ui.MUTED);colorName.setPadding(0,0,0,0);words.addView(colorName);row.addView(words,new LayoutParams(0,-2,1));TextView arrow=label("›",24,Ui.MUTED);arrow.setPadding(dp(8),0,0,0);row.addView(arrow);updateColorRow();row.setOnClickListener(v->{int original=Color.parseColor(value.optString("backgroundColor","#000000"));boolean[] committed={false};AppSheet sheet=new AppSheet(activity,"背景颜色","选择色块，或在面板上自由调色",null);WallpaperColorPicker picker=new WallpaperColorPicker(activity,original,color->{VideoApp.put(value,"backgroundColor",String.format(Locale.ROOT,"#%06X",color&0xffffff));updateColorRow();changed();});sheet.field(picker);sheet.dialog.setOnDismissListener(d->{if(!committed[0]){VideoApp.put(value,"backgroundColor",String.format(Locale.ROOT,"#%06X",original&0xffffff));updateColorRow();changed();}});sheet.footerButton("取消",false,()->sheet.dialog.dismiss());sheet.footerButton("使用此颜色",true,()->{committed[0]=true;sheet.dialog.dismiss();});sheet.show();});control(row);
 }
 private void buildVideo(){
  removeAllViews();videoCard=null;palette=null;heading("运动响应");choice("motionMode","响应方式",new String[]{"disabled","device","scroll"},new String[]{"关闭","设备倾斜","桌面滚动"});if(value.optString("motionMode").equals("device"))slider("strength","运动强度",0,1,"");
  if(value.optString("motionMode").equals("scroll")){choice("pageMode","背景分段",new String[]{"auto","manual"},new String[]{"自动","自定义"});if(value.optString("pageMode").equals("manual"))slider("fallbackPages","分段页数",1,12," 页");control(label(value.optString("pageMode").equals("manual")?"每次翻页移动一段背景":"按画面比例分段，并同步系统提供的桌面页数",11,Ui.MUTED));}
  heading("播放与构图");toggle("flip","水平镜像",true);slider("speed","播放速度",.25f,2,"×");choice("alignment","画面适配",new String[]{"cover","fill","free"},new String[]{"铺满","拉伸","自由"});if(value.optString("alignment").equals("free")){slider("zoom","缩放",1,2.5f,"×");slider("x","水平位置",-.5f,.5f,"");slider("y","垂直位置",-.5f,.5f,"");}backgroundColor();
  heading("颜色调节");toggleRebuild("showColorOptions","调整画面颜色");if(value.optBoolean("showColorOptions",true)){slider("brightness","亮度",.2f,1.8f,"×");slider("contrast","对比度",0,2,"×");slider("saturation","饱和度",0,2,"×");slider("hue","色相",-180,180,"°");}
  heading("节能");toggle("batteryStatic","省电时保持静态画面",true);control(label("退出系统省电模式后，自动恢复播放",11,Ui.MUTED));videoCard=null;TextView reset=label("重置视频设置",13,Ui.MUTED);reset.setGravity(Gravity.CENTER);reset.setMinHeight(dp(48));reset.setOnClickListener(v->{value=EffectOptions.video(null);build();changed();});addView(reset);
 }
 private void toggleRebuild(String key,String title){Switch control=new Switch(activity);control.setText(title);control.setTextColor(Ui.TEXT);control.setTextSize(13);control.setThumbTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Ui.ACCENT,0xff81909f}));control.setTrackTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xff355c51,0xff303d4b}));control.setMinHeight(dp(46));control.setChecked(value.optBoolean(key,true));control.setOnCheckedChangeListener((v,on)->{VideoApp.put(value,key,on);build();changed();});control(control);}
 private void build(){if(kind.equals("video")){buildVideo();return;}palette=null;removeAllViews();heading("运动与交互");toggle("gyro",hasSensor?"随手机倾斜产生视差":"此设备未提供可用姿态传感器",hasSensor);toggle("touch","触摸拖动画面",true);toggle("reverseX","反转水平倾斜",true);toggle("reverseY","反转垂直倾斜",true);slider("strength","倾斜强度",0,1,"");slider("smooth","运动平滑时间",.03f,1," 秒");slider("touchStrength","拖动幅度",0,1,"");choice("pageMode","图片分割页数",new String[]{"auto","manual"},new String[]{"自动","自定义"});if(value.optString("pageMode").equals("manual"))slider("fallbackPages","自定义桌面页数",1,12," 页");addView(label("自动按画面比例分割，优先使用系统提供的页数；也可自定义分段。",11,Ui.MUTED));
  heading("节能");toggle("batteryStatic","系统省电模式下暂停为静态画面",true);heading("构图与画面");slider("zoom","缩放",1,2.5f,"×");slider("x","水平位置",-.5f,.5f,"");slider("y","垂直位置",-.5f,.5f,"");slider("rotation","画面旋转",-15,15,"°");slider("brightness","亮度",.2f,1.8f,"×");slider("saturation","饱和度",0,2,"×");if(kind.equals("scene"))slider("layerDepth","分层视差深度",0,2,"×");
  heading("动画与叠加");toggle("ripple","触摸波纹",true);toggle("particles","漂浮粒子",true);slider("particleCount","粒子数量",4,100,"");if(!kind.equals("animated"))slider("speed",kind.equals("video")?"视频播放速度":"粒子运动速度",.25f,2,"×");slider("fps","绘制帧率",15,60," 帧/秒");
  palette=new LinearLayout(activity);palette.setOrientation(VERTICAL);palette.addView(label("波纹与粒子颜色",13,Ui.TEXT));paletteHint=label("",12,Ui.MUTED);palette.addView(paletteHint);LinearLayout colors=new LinearLayout(activity);String[] values={"#a9efd5","#8ebdff","#ffadc4","#ffd48e","#ffffff"},names={"薄荷绿","天空蓝","樱花粉","暖金色","白色"};
  for(int i=0;i<values.length;i++){final String color=values[i],name=names[i];TextView choice=label("",24,Color.parseColor(color));choice.setTag(color);choice.setGravity(Gravity.CENTER);choice.setPadding(0,0,0,0);choice.setContentDescription(name);choice.setOnClickListener(v->{VideoApp.put(value,"color",color);updatePalette();choice.announceForAccessibility("已选择"+name);changed();});colors.addView(choice,new LayoutParams(0,dp(46),1));}palette.addView(colors);addView(palette);updatePalette();

  TextView reset=label("恢复默认效果",13,Ui.ACCENT);reset.setGravity(Gravity.CENTER);reset.setMinHeight(dp(46));reset.setOnClickListener(v->{value=EffectOptions.normalize(null);build();changed();});addView(reset);if(layerCount>0)sceneLayers(layerDepths,layerNames,xray);
 }
}
